#!/usr/bin/env bash
# Commit the freshly generated shop data and push it to main, surviving collisions with other runs or pushes.
#
# Used by .github/workflows/sync-catalog.yml. The data is DERIVED (it can always be regenerated from the CMS), so when the push is
# rejected because someone else updated main first, the right move is NOT to merge/rebase their version of the generated files (which
# can conflict). Instead: take their main as it is, regenerate on top of it, check it again, and push again.
#
# Exit codes: 0 = published or nothing to publish, 1 = a real problem (data check failed, git error, too many collisions).
# Sets "changed=true|false" in $GITHUB_OUTPUT when that file exists.
set -uo pipefail

GEN="${SYNC_GEN:-python scripts/gen-catalog.py}"
PRUNE="${SYNC_PRUNE:-python scripts/prune-photos.py}"
VALIDATE="${SYNC_VALIDATE:-python scripts/validate-data.py}"
SUMMARISE="${SYNC_SUMMARISE:-python scripts/catalog-summary.py}"
PATHS="${SYNC_PATHS:-src/data public/img/products public/img/reels}"
OUT="${GITHUB_OUTPUT:-/dev/null}"

publish() {   # 0 pushed, 10 nothing changed, 2 push rejected, 1 other failure
  # only folders that exist (a missing one would make git refuse the whole command)
  local existing=() p
  for p in $PATHS; do [ -e "$p" ] && existing+=("$p"); done
  git add -A "${existing[@]}" || return 1
  if git diff --cached --quiet; then return 10; fi
  local summary
  summary="$($SUMMARISE 2>/dev/null)" || summary="catalog updated"
  git commit -q -m "Sync catalog from ANVEDA" -m "$summary" -m "Generated by .github/workflows/sync-catalog.yml" || return 1
  git push -q && return 0
  return 2
}

regenerate() {
  $GEN && $PRUNE && $VALIDATE
}

for attempt in 1 2 3 4 5; do
  publish; rc=$?
  case "$rc" in
    0)  echo "Published."; echo "changed=true" >> "$OUT"; exit 0 ;;
    10) echo "Catalog unchanged: nothing to publish."; echo "changed=false" >> "$OUT"; exit 0 ;;
    2)  echo "Push rejected (attempt $attempt of 5): main was updated by someone else. Starting again from their version."
        git fetch -q origin main || { echo "::error::could not fetch main"; exit 1; }
        git reset -q --hard origin/main || exit 1
        regenerate || { echo "::error::regenerating the data on top of the new main failed"; exit 1; }
        sleep $(( attempt * 3 + RANDOM % 5 )) ;;
    *)  echo "::error::git failed while saving the data (code $rc)"; exit 1 ;;
  esac
done
echo "::error::The push was still being rejected after 5 attempts, so this run gave up. The next run will try again."
exit 1
